"""Check all archives generated by the Arduino build, excluding the SDK."""
from collections import Counter
import datetime
import hashlib
import json
from pathlib import Path
import subprocess

build = Path(r'C:\workspace\tab5-build-0828-clang')
qa = Path(r'C:\workspace\tab5-qa-0828-clang')
ar = Path(r'C:\Espressif\tools\esp-clang\esp-20.1.1_20250829\esp-clang\bin\llvm-ar.exe')
expected = {}
for category in ['sketch', 'libraries']:
    for obj in (build / category).rglob('*.o'):
        expected.setdefault(obj.parent / 'objs.a', []).append(obj)
core = list((build / 'core').rglob('*.o'))
if core:
    expected[build / 'core' / 'core.a'] = core
if not expected:
    raise RuntimeError('No generated object files found.')
rows = []
errors = []
for archive, objects in sorted(expected.items()):
    row = {'archive': archive.relative_to(build).as_posix(), 'expectedObjects': len(objects)}
    if not archive.is_file():
        row['error'] = 'Generated archive missing'
        errors.append(row)
        rows.append(row)
        continue
    result = subprocess.run([str(ar), 't', str(archive)], capture_output=True, text=True)
    members = Counter(result.stdout.splitlines())
    names = Counter(obj.name for obj in objects)
    missing = list((names - members).elements())
    unexpected = list((members - names).elements())
    row.update({'memberCount': sum(members.values()), 'missingMembers': missing,
                'unexpectedMembers': unexpected, 'readExitCode': result.returncode,
                'bytes': archive.stat().st_size,
                'sha256': hashlib.sha256(archive.read_bytes()).hexdigest()})
    if result.returncode or missing or unexpected:
        row['error'] = result.stderr.strip() or 'Archive members differ from generated objects'
        errors.append(row)
    rows.append(row)
report = {'checkedAt': datetime.datetime.now(datetime.timezone.utc).isoformat(),
          'archives': rows, 'archiveCount': len(rows),
          'objectCount': sum(len(objects) for objects in expected.values()),
          'errors': errors, 'passed': not errors}
(qa / 'archive-verification.json').write_text(json.dumps(report, indent=2), encoding='utf-8')
print(json.dumps({key: report[key] for key in ['checkedAt', 'archiveCount', 'objectCount', 'errors', 'passed']}, indent=2))
raise SystemExit(0 if not errors else 1)
